def parse_price(s: str) -> float:
    import re
    match = re.search(r"\$([0-9,]+)\.?([0-9]*)", s)
    if not match:
        raise ValueError("Invalid price format")
    dollars, cents = match.groups()
    dollars = dollars.replace(",", "")
    return float(dollars + (cents or "0") + "0" * (2 - len(cents)))

